mapper.select:
select t.classes_name,t.classes_name classesName,t.heartbeat_time,t.heartbeat_time
heartbeatTime,t.impl_bean,t.impl_bean implBean,t.classes_id,t.classes_id classesId,t.machine_id,t.machine_id
machineId,t.machine_code,t.machine_code machineCode,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.machine_name,t.machine_name
machineName,t.machine_ip,t.machine_ip machineIp,t.create_time createTime
from attendance_machine t
where 1 =1

    and t.classes_name= #{classesName}


    and t.heartbeat_time= #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.classes_id= #{classesId}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}

order by t.create_time desc

    limit #{page}, #{row}

